#include <iostream>
#include <cstring>

int main() {
    const char text[] = "A zoo has many animals including zebras";
    int searchChar = 'z';

    // Tim vi tri xuat hien dau tien bang strchr
    const char* first = std::strchr(text, searchChar);
    if (first != nullptr) {
        std::cout << "First '" << static_cast<char>(searchChar) << "' found at index: "
                  << (first - text) << " -> \"" << first << "\"\n";
    }

    // Tim vi tri xuat hien cuoi cung bang strrchr
    const char* last = std::strrchr(text, searchChar);
    if (last != nullptr) {
        std::cout << "Last '" << static_cast<char>(searchChar) << "' found at index: "
                  << (last - text) << " -> \"" << last << "\"\n";
    }

    // Tim ky tu khong ton tai
    const char* notFound = std::strchr(text, 'k');
    if (notFound == nullptr) {
        std::cout << "'k' was not found.\n";
    }

    return 0;
}

#include <iostream>
#include <cstring>

int main() {
    const char source[] = "The price is 450 dollars.";
    const char digits[] = "0123456789";

    // 1. Su dung strcspn de lay do dai phan chu truoc con so
    std::size_t prefixLen = std::strcspn(source, digits);
    std::cout << "Prefix length before first digit: " << prefixLen << '\n';

    // 2. Su dung strpbrk de lay con tro toi ky tu so dau tien
    const char* firstDigitPtr = std::strpbrk(source, digits);
    if (firstDigitPtr != nullptr) {
        std::cout << "First digit found: '" << *firstDigitPtr << "'\n";
        std::cout << "Remaining substring starting at first digit: \""
                  << firstDigitPtr << "\"\n";
    }

    // 3. Tim ky tu khong he ton tai
    const char punctuation[] = ";!?";
    const char* noMatch = std::strpbrk(source, punctuation);
    std::cout << "Punctuation (;!?) found? "
              << (noMatch != nullptr ? "Yes" : "No") << '\n';

    return 0;
}

#include <iostream>
#include <cstring>
#include <string_view>

int main() {
    const char s1[] = "The value is 3.14159";
    const char allowed[] = "aehi lsTuv";

    // Using std::strspn
    std::size_t span_len = std::strspn(s1, allowed);
    std::cout << "strspn span: " << span_len << "\n";

    // Using std::strstr
    const char text[] = "abcdefabcdef";
    const char target[] = "def";
    const char *found = std::strstr(text, target);
    if (found != nullptr) {
        std::cout << "strstr remainder: " << found << "\n";
    }

    // Modern C++17 string_view equivalent
    std::string_view sv{text};
    auto pos = sv.find(target);
    if (pos != std::string_view::npos) {
        std::cout << "string_view pos: " << pos << "\n";
    }
    return 0;
}
